    fundingStart = time;
}

function setStartRefund(bool s) external {
    startRefund = s;
}

function getExchangeRate(address investorAddress) constant returns (uint){
    if(initialInvestor[investorAddress])
        return EarlyInvestorExchangeRate;
    else
        return exchangeRate;
}

function ICOopen() constant returns (bool){
    if(!funding) throw;
    if(block.timestamp < fundingStart) throw;
    return true;
}

function refund() external {
    if(!startRefund) throw;
    userBalance = balances[msg.sender];
    balances[msg.sender] = 0;
    balancesEther[msg.sender] = 0;
    totalTokens -= userBalance;
    Transfer(msg.sender, master, userBalance);
    if (!master.send(this.balance)) throw;
}

function transferFrom(address _from, address _to, uint256 _amount) returns (bool success) {
    if(msg.sender != master) throw;
    if(_to != migrationAgent) throw;
    if(balances[_from] >= _amount
        && allowed[_from][msg.sender] >= _amount
        && _amount > 0) {
        balances[_from] -= _amount;
        allowed[_from][msg.sender] -= _amount;
        balances[_to] += _amount;
        Transfer(_from, _to, _amount);
        return true;
    } else {
        return false;
    }
}

function approve(address _spender, uint256 _amount) returns (bool success) {
    if(msg.sender != master) throw;
    if(_spender != migrationAgent) throw;
    allowed[msg.sender][_spender] = _amount;
    Approval(msg.sender, _spender, _amount);
    return true;
}

function allowance(address _owner, address _spender) constant returns (uint256 remaining) {
    if(msg.sender != master) throw;
    if(_spender != migrationAgent) throw;
    return allowed[_owner][_spender];
}

function migrate(uint256 _value) external {
    if(msg.sender != master) throw;
    if(migrationAgent == 0) throw;
    userBalance = balances[msg.sender];
    balances[msg.sender] -= _value;
    totalTokens -= _value;
    totalMigrated += _value;
    MigrationAgent(migrationAgent).migrateFrom(msg.sender, _value);
    Migrate(msg.sender, migrationAgent, _value);
    if (!msg.sender.send(this.balance)) throw;
}

